scripts.check:ci:
bun -e '
const workflow = ".github/workflows/ci.yml";
const file = Bun.file(workflow);
if (!(await file.exists())) {
  console.error("check:ci: " + workflow + " is missing; every guard in this project would then run only by hand");
  process.exit(1);
}
const yml = await file.text();
const scripts = (await Bun.file("package.json").json()).scripts;
const guards = Object.keys(scripts).filter((key) => key.startsWith("check:"));
const commands = ["bun run typecheck", "bun test", ...guards.map((key) => "bun run " + key)];
const uncommented = yml.split("\n").map((line) => line.split("#")[0]);
const invocations = uncommented
  .map((line) => /^\s*-?\s*run:\s*(.*)$/.exec(line))
  .filter((match) => match !== null)
  .map((match) => match[1].trim());
const invoked = (command) =>
  invocations.some((step) => step === command || step.startsWith(command + " "));
const missing = commands.filter((command) => !invoked(command));
const pinned = uncommented.some((line) => /^\s*bun-version:\s*"?1\.2\.18"?\s*$/.test(line));
if (!pinned) missing.push("bun-version: 1.2.18 (the runtime must stay pinned)");
if (missing.length > 0) {
  console.error("check:ci: " + workflow + " never runs: " + missing.join(", "));
  process.exit(1);
}
'

scripts.check:readme:
test -f README.md || { echo 'check:readme: README.md is missing; every disclosure below would pass over nothing'; exit 1; }
grep -A 25 'does not protect you against' README.md | grep -q 'post-compromise' || {
  echo 'check:readme: post-compromise gap not disclosed'; exit 1; }
grep -A 25 'does not protect you against' README.md | grep -q 'unrecoverable' || {
  echo 'check:readme: forward-secrecy claim not stated'; exit 1; }
grep -q 'operates no relay' README.md || {
  echo 'check:readme: the README does not say the project operates no relay'; exit 1; }
grep -q 'sees who connects, from what IP and when' README.md || {
  echo 'check:readme: the README does not say what whoever runs a relay sees'; exit 1; }

scripts.check:unaudited:
for f in README.md src/tui/StatusBar.tsx; do
  test -f "$f" || { echo "check:unaudited: $f is missing; the banner would be checked against nothing"; exit 1; }
  grep -q 'unaudited' "$f" || { echo "check:unaudited: $f does not carry the word 'unaudited'"; exit 1; }
done
